<template><main class="page"><header><button @click="$router.push('/')">← 返回主页</button><h1>记忆的迷宫</h1></header><section class="hero"><p class="tag">MEMORY MAZE</p><h2>在看不见的路上<br>记住每一次碰撞</h2><p>创建房间后，可选择双人经典竞速，或支持 1–4 人的定向越野。</p><div><button class="primary" :disabled="store.creatingRoom" @click="createRoom">{{store.creatingRoom?'创建中…':'创建房间'}}</button><button @click="load">刷新房间</button></div></section><section class="rooms"><button v-for="room in store.rooms" :key="room.id" class="room" @click="join(room.id)"><span><b>房间 {{room.id}}</b><small>房主 {{room.owner}}</small></span><span>{{room.players.length}} / {{room.maxPlayers}} 人</span><em>{{room.status==='waiting'?'等待中':room.status}}</em></button><p v-if="!store.rooms.length">暂时没有开放房间，创建一间开始探索吧。</p></section><p v-if="store.notice" class="error">{{store.notice}}</p></main></template>
<script setup>
import {onMounted,watch} from 'vue';import {useRouter} from 'vue-router';import {useMazeRaceStore} from '@/stores/mazeRaceStore';const store=useMazeRaceStore(),router=useRouter();watch(()=>store.room_id,id=>{if(id)router.push({name:'MazeRaceRoom',params:{roomId:id}})});async function createRoom(){try{await store.createRoom()}catch(e){store.notice=e.response?.data?.detail||e.message}}async function join(id){try{await store.enterRoom(id)}catch(e){store.notice=e.response?.data?.detail||e.message}}async function load(){try{await store.fetchRooms()}catch(e){store.notice=e.message}}onMounted(load);
</script>
<style scoped>
.page{min-height:100vh;padding:28px;color:#f4ffef;font-family:system-ui;background:radial-gradient(circle at 20% 10%,#86b94c55,transparent 30%),linear-gradient(145deg,#2e6332,#102d1c 72%)}header{display:flex;align-items:center;max-width:900px;margin:auto}header h1{margin:auto}.hero,.rooms{max-width:820px;margin:32px auto}.hero{text-align:center;padding:45px;border:1px solid #ffffff2d;border-radius:26px;background:#153c24b8;box-shadow:0 25px 70px #071d10aa}.tag{letter-spacing:.22em;color:#cce795}.hero h2{font-size:clamp(32px,6vw,58px);line-height:1.08;margin:10px}.hero div{display:flex;justify-content:center;gap:12px;margin-top:24px}button{border:0;border-radius:11px;padding:11px 18px;cursor:pointer}.primary{background:#d9f3a2;color:#17351d;font-weight:900}.rooms{display:grid;gap:12px}.room{display:grid;grid-template-columns:1fr auto auto;align-items:center;gap:20px;text-align:left;background:#efffdd;color:#173b21}.room span:first-child{display:grid}.room small{color:#59705d}.room em{font-style:normal;color:#39703e}.error{text-align:center;color:#ffb0a5}@media(max-width:600px){.hero{padding:30px 18px}.room{grid-template-columns:1fr auto}.room em{display:none}}
</style>
